package ama.api;
import ama.transcript.*;import ama.storage.*;import ama.minutes.ControlledMinutesDataSource;import ama.contract.IdentityContracts.*;import ama.contract.ProcessingContracts.*;import java.util.*;import java.nio.file.*;import java.sql.*;import java.lang.reflect.*;import javax.sql.DataSource;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.core.env.*;import com.fasterxml.jackson.databind.ObjectMapper;
/** Real intake acceptance writes followed by actual JDBC failure; all business rows must rollback. */
public final class LocalIntakeRollbackCheck {
 static void check(boolean b,String m){if(!b)throw new IllegalStateException(m);}
 static final class Source extends AbstractDataSource {
  final DataSource delegate;String target;boolean inserted;int changed;Source(DataSource d){delegate=d;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> t,InvocationHandler h){return Proxy.newProxyInstance(t.getClassLoader(),new Class[]{t},h);}
  Connection wrap(Connection actual){return(Connection)proxy(actual,Connection.class,(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object result=invoke(actual,m,a);if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&result instanceof PreparedStatement st)return proxy(st,PreparedStatement.class,(s,sm,sa)->{Object value=invoke(st,sm,sa);if(target!=null&&sm.getName().equals("executeUpdate")){changed++;if(!inserted&&sql.startsWith("INSERT INTO "+target+"(")){check(value instanceof Number n&&n.intValue()==1&&!actual.getAutoCommit()&&org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive(),"Actual single row uncommitted write required");inserted=true;throw new SQLException("LOCAL_AFTER_REAL_INTAKE_"+target);}}return value;});return result;});}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 static Map<String,Object> snapshot(JdbcTemplate j,String meeting){var s=new LinkedHashMap<>(LocalMeetingInfoRollbackCheck.snapshot(j,meeting));for(String t:List.of("input_batch","transcription_input","file_object"))s.put(t,j.queryForObject("SELECT COUNT(*) FROM "+t+" WHERE meeting_id=?",Long.class,meeting));s.put("batchFiles",j.queryForObject("SELECT COUNT(*) FROM input_batch_file f JOIN input_batch b ON b.id=f.batch_id WHERE b.meeting_id=?",Long.class,meeting));s.put("profiles",j.queryForObject("SELECT COUNT(*) FROM input_batch_fingerprint_profile f JOIN input_batch b ON b.id=f.batch_id WHERE b.meeting_id=?",Long.class,meeting));s.put("refs",j.queryForList("SELECT r.* FROM file_reference r JOIN file_object f ON f.id=r.file_id WHERE f.meeting_id=? ORDER BY r.file_id,r.owner_kind,r.owner_id,r.purpose",meeting));s.put("subject",j.queryForList("SELECT * FROM task_subject WHERE subject_kind='MEETING' AND subject_id=?",meeting));s.put("outboxSequence",j.queryForObject("SELECT next_id FROM task_outbox_sequence WHERE id=1",Long.class));return s;}
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==2,"Explicit owned daily intake qualification required");Path file=Path.of(args[0]).toRealPath();check(file.getParent().endsWith(Path.of(".tools/local-app")),"Owned current configuration required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url"),meeting=args[1];check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Owned DB required");UUID.fromString(meeting);var source=new Source(ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password")));var j=new JdbcTemplate(source);j.setQueryTimeout(5);var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var configured=ConfiguredProcessing.read(env);var actor=new Actor("dev-owner",Status.ACTIVE,Set.of(Role.USER));
  try(var definitions=ConfiguredBackends.read(env);var client=ConfiguredPublication.read(env,configured.read(),configured.index()).client()){
   var catalog=new FileBackendCatalog(source,definitions.backends(),definitions.defaultId());catalog.configure();var runtime=LocalAcquisitionBudgetCheck.build(source,env,catalog,client);var intake=new ProcessingConfiguration().processingIntake(source,runtime.tx(),runtime.access(),runtime.processing(),runtime.fences(),runtime.queue(),runtime.outbox(),runtime.processing().preparation());var fileIds=j.queryForList("SELECT f.file_id FROM input_batch_file f JOIN input_batch b ON b.id=f.batch_id WHERE b.meeting_id=? ORDER BY b.base_revision DESC,f.ordinal LIMIT 2",String.class,meeting);check(fileIds.size()==2,"Genuine retained two-file origin required");long revision=j.queryForObject("SELECT revision FROM meeting WHERE id=? AND ever_published=0 AND final_confirmation_id IS NULL",Long.class,meeting);var request=new ImportRequest(revision,fileIds);var before=snapshot(j,meeting);var cases=new ArrayList<Map<String,Object>>();runtime.tx().required(()->{try{intake.accept(actor,meeting,UUID.randomUUID().toString(),request,UUID.randomUUID().toString());throw new AssertionError("Ambient intake must reject");}catch(IllegalStateException expected){check(expected.getMessage().equals("Standalone processing intake required"),"Exact ambient guard required");}return null;});check(before.equals(snapshot(j,meeting)),"Ambient guard must preserve snapshot");
   for(String target:List.of("input_batch_file","transcription_input","durable_task","task_outbox")){
    source.target=target;source.inserted=false;source.changed=0;RuntimeException rejected=null;try{intake.accept(actor,meeting,UUID.randomUUID().toString(),request,UUID.randomUUID().toString());}catch(RuntimeException failure){rejected=failure;}finally{source.target=null;}boolean intended=false;for(Throwable cause=rejected;cause!=null;cause=cause.getCause())if(cause instanceof SQLException&&cause.getMessage().equals("LOCAL_AFTER_REAL_INTAKE_"+target))intended=true;check(source.inserted&&source.changed>0&&intended,"Only actual intended post-write failure qualifies for "+target);check(before.equals(snapshot(j,meeting)),"Root/input/refs/task/receipt/audit/outbox/sequence must rollback for "+target);cases.add(Map.of("table",target,"actualUncommittedInsert",true,"executedMutatingStatements",source.changed,"intendedSqlException",true,"snapshotUnchanged",true));
   }
   System.out.println(new ObjectMapper().writeValueAsString(Map.of("pass",true,"meetingId",meeting,"genuineFactoriesAndSharedInstances",true,"ambientRejected",true,"cases",cases,"zeroAcceptedTask",true,"manualSqlBusinessFixtures",false)));
  }
 }
}
